// ==================================================================
// TERRACORRIDOR SHARED ADAPTER PRELUDE (identical copy in W5 and W6)
// All upstream mappings (W1-W4), fixtures and the build-score formula
// live here. Edit ONLY this block to integrate W2/W3/W4.
// ==================================================================
const integrations = {
  demoMode: false,                       // true => mock fixtures allowed (always labelled demo_fixture)
  corridorId: "ab-strathcona-demo",
  segmentsTable: "euUFpWZEDrrDJOkc",  // W1 corridor_segments
  predictionsTable: "7T6RlFe9HRFOfkCD",  // W2 corridor_predictions (one row per segment and horizon)
  baselinesTable: "LckNoZvtBFwDnwM3",  // W2 corridor_baselines (slope, NDVI, baseline days)
  alertsTable: "sPlAgvMC7Q6sFHho",  // W3 near-term state lives in corridor_watch
  auditTable: "fWeMlbL9wQ5I7m3N",  // W4 corridor_work_orders (approval status per segment)
  buildTable: "E1GpvXaFTP4qLjsW",  // W5 corridor_build
  reportsTable: "T0PP8Zebw0vWU5KW",  // W5 corridor_reports
  configTable: "qfz2KdlrPsXlGkYO"  // W5 corridor_build_config
};

const DEFAULT_CONFIG = {
  acresPerMW: 6, performanceRatio: 0.8, leaseRatePerAcreYr: 400, partnerShare: 0.5,
  gridEmissionFactor: 0.5, maxBuildSlopePct: 10, riskPenaltyMultiplier: 0.5,
  powerPricePerMWh: 60,      // sample assumption (extension) - gross electricity value only, NOT lease revenue
  exclusionBandM: 30,        // metres each side of the centreline (approximation, see methodology)
  buildStripM: 60,          // total panel width across both sides, outside the exclusion band
  studyStripWidthM: 200      // strip width in metres each side, measured from the edge of the exclusion band (matches W1 geometry)
};
const RANGES = {
  acresPerMW: [1, 50], performanceRatio: [0.3, 1], leaseRatePerAcreYr: [0, 100000], partnerShare: [0, 1],
  gridEmissionFactor: [0, 2], maxBuildSlopePct: [1, 45], riskPenaltyMultiplier: [0, 1],
  powerPricePerMWh: [0, 2000], exclusionBandM: [0, 100], buildStripM: [10, 400], studyStripWidthM: [50, 500]
};

function num(v) { if (v === null || v === undefined || v === "") return null; const n = Number(v); return isFinite(n) ? n : null; }
function round(v, d) { if (v === null || v === undefined || !isFinite(v)) return null; const f = Math.pow(10, d); return Math.round(v * f) / f; }
function clamp01(x) { return Math.max(0, Math.min(1, x)); }
function nowIso() { return new Date().toISOString(); }
function pick(r, keys) { for (let i = 0; i < keys.length; i++) { const v = r[keys[i]]; if (v !== undefined && v !== null && v !== "") return v; } return null; }
function haversineKm(lat1, lon1, lat2, lon2) {
  const R = 6371, rad = Math.PI / 180;
  const dLat = (lat2 - lat1) * rad, dLon = (lon2 - lon1) * rad;
  const a = Math.sin(dLat / 2) * Math.sin(dLat / 2) + Math.cos(lat1 * rad) * Math.cos(lat2 * rad) * Math.sin(dLon / 2) * Math.sin(dLon / 2);
  return 2 * R * Math.asin(Math.sqrt(a));
}
function toArr(v) {
  if (Array.isArray(v)) return v;
  if (typeof v === "string" && v) { try { const p = JSON.parse(v); if (Array.isArray(p)) return p; } catch (e) {} return v.split(",").map(function (x) { return x.trim(); }).filter(Boolean); }
  return [];
}
function toObj(v) { if (v && typeof v === "object") return v; if (typeof v === "string" && v) { try { const p = JSON.parse(v); if (p && typeof p === "object") return p; } catch (e) {} } return null; }
function normTier(t) {
  if (t === null || t === undefined) return "unverified";
  const s = String(t).toLowerCase().trim();
  const m = { green: "green", low: "green", amber: "amber", yellow: "amber", watch: "amber", medium: "amber", red: "red", high: "red", "red-uncertain": "red-uncertain", red_uncertain: "red-uncertain" };
  return m[s] || "unverified";
}
function riskTier(score, agreement) {
  if (score >= 66) return agreement < 0.6 ? "red-uncertain" : "red";
  if (score >= 40) return "amber";
  return "green";
}
function validateAssumptions(obj) {
  const clean = {}, errors = [];
  if (obj === null || obj === undefined) return { clean: clean, errors: errors };
  if (typeof obj !== "object" || Array.isArray(obj)) return { clean: clean, errors: ["assumptions must be an object"] };
  Object.keys(obj).forEach(function (k) {
    if (!RANGES[k]) { errors.push("unknown assumption: " + k); return; }
    const v = num(obj[k]);
    if (v === null || v < RANGES[k][0] || v > RANGES[k][1]) errors.push(k + " must be a number between " + RANGES[k][0] + " and " + RANGES[k][1]);
    else clean[k] = v;
  });
  return { clean: clean, errors: errors };
}

// ---------- W1 geometry helpers ----------
function offsetPoly(a, b, off1, off2) {
  const lat0 = (a[1] + b[1]) / 2, cl = Math.cos(lat0 * Math.PI / 180);
  const dx = (b[0] - a[0]) * 111320 * cl, dy = (b[1] - a[1]) * 111320;
  const L = Math.sqrt(dx * dx + dy * dy) || 1, nx = -dy / L, ny = dx / L;
  function pt(p, o) { return [p[0] + (nx * o) / (111320 * cl), p[1] + (ny * o) / 111320]; }
  return [pt(a, off1), pt(b, off1), pt(b, off2), pt(a, off2), pt(a, off1)];
}
function syntheticSegments(corridorId, count) {
  const pts = [];
  for (let i = 0; i <= count; i++) pts.push([-113.36 + i * 0.0151, 53.545 + 0.004 * Math.sin(i / 2.5) + 0.0006 * i]);
  const out = [], gen = nowIso();
  for (let i = 0; i < count; i++) {
    const a = pts[i], b = pts[i + 1];
    const fc = { type: "FeatureCollection", features: [
      { type: "Feature", properties: { kind: "centreline", synthetic: true }, geometry: { type: "LineString", coordinates: [a, b] } },
      { type: "Feature", properties: { kind: "exclusion_band", width_m: 30, synthetic: true }, geometry: { type: "Polygon", coordinates: [offsetPoly(a, b, -30, 30)] } },
      { type: "Feature", properties: { kind: "study_strip", side: "left", synthetic: true }, geometry: { type: "Polygon", coordinates: [offsetPoly(a, b, 30, 200)] } },
      { type: "Feature", properties: { kind: "study_strip", side: "right", synthetic: true }, geometry: { type: "Polygon", coordinates: [offsetPoly(a, b, -200, -30)] } }
    ] };
    out.push({
      segment_id: "synthetic_seg_" + (i < 10 ? "0" : "") + i, corridor_id: corridorId, segment_index: i,
      lat_start: a[1], lon_start: a[0], lat_end: b[1], lon_end: b[0],
      length_m: Math.round(haversineKm(a[1], a[0], b[1], b[0]) * 1000),
      polygon_geometry_json: JSON.stringify(fc),
      bbox_south: Math.min(a[1], b[1]) - 0.002, bbox_west: Math.min(a[0], b[0]) - 0.003, bbox_north: Math.max(a[1], b[1]) + 0.002, bbox_east: Math.max(a[0], b[0]) + 0.003,
      status: "active", source_hash: "", source_kind: "synthetic_fallback", generated_at: gen
    });
  }
  return out;
}
function resolveSegments(rows) {
  const live = rows.filter(function (r) { return r && r.segment_id && (!r.corridor_id || r.corridor_id === integrations.corridorId) && r.status !== "inactive"; });
  if (live.length) { live.sort(function (x, y) { return (num(x.segment_index) || 0) - (num(y.segment_index) || 0); }); return { segments: live, source: "w1_live" }; }
  if (integrations.demoMode) return { segments: syntheticSegments(integrations.corridorId, 12), source: "synthetic_fallback" };
  return { segments: [], source: "missing" };
}
function classifyFeature(f) {
  const t = (JSON.stringify(f.properties || {}) + " " + ((f.properties || {}).kind || "")).toLowerCase();
  const g = f.geometry && f.geometry.type;
  if (t.indexOf("exclu") >= 0 || t.indexOf("buffer") >= 0) return "exclusion_band";
  if (t.indexOf("strip") >= 0 || t.indexOf("study") >= 0) return "study_strip";
  if (t.indexOf("centre") >= 0 || t.indexOf("center") >= 0 || t.indexOf("pipeline") >= 0) return "centreline";
  if (g === "LineString" || g === "MultiLineString") return "centreline";
  return "study_strip";
}
function parseGeometry(seg) {
  const out = { centreline: [], exclusion_band: [], study_strips: [], status: "ok" };
  let fc = null;
  try { fc = JSON.parse(seg.polygon_geometry_json); } catch (e) { fc = null; }
  const feats = fc && fc.type === "FeatureCollection" && Array.isArray(fc.features) ? fc.features : (fc && fc.type === "Feature" ? [fc] : []);
  feats.forEach(function (f) {
    if (!f || !f.geometry) return;
    const role = classifyFeature(f);
    if (role === "centreline") out.centreline.push(f); else if (role === "exclusion_band") out.exclusion_band.push(f); else out.study_strips.push(f);
  });
  if (!out.centreline.length) {
    const a = [num(seg.lon_start), num(seg.lat_start)], b = [num(seg.lon_end), num(seg.lat_end)];
    if (a[0] !== null && a[1] !== null && b[0] !== null && b[1] !== null) {
      out.centreline.push({ type: "Feature", properties: { kind: "centreline", derived: "from segment endpoints" }, geometry: { type: "LineString", coordinates: [a, b] } });
      out.status = "derived_centreline";
    } else out.status = "invalid";
  }
  return out;
}

// ---------- W2 / W3 / W4 ADAPTERS (proposed interfaces, NOT confirmed schemas) ----------
function adaptPrediction(r) {
  return {
    segment_id: r.segment_id,
    risk5_score: num(pick(r, ["risk5_score", "risk_5y_score", "risk_score_5y", "score_5y"])),
    risk5_tier: normTier(pick(r, ["risk5_tier", "risk_5y_tier", "tier_5y"])),
    risk10_score: num(pick(r, ["risk10_score", "risk_10y_score", "risk_score_10y", "score_10y"])),
    risk10_tier: normTier(pick(r, ["risk10_tier", "risk_10y_tier", "tier_10y"])),
    drivers: toArr(pick(r, ["drivers", "risk_drivers", "top_drivers"])),
    model_agreement: num(pick(r, ["model_agreement", "agreement"])),
    ndvi_trend: num(pick(r, ["ndvi_trend", "vegetation_trend"])),
    slope_pct: num(pick(r, ["slope_pct", "slope_percent", "slope"])),
    freeze_thaw_trend: num(pick(r, ["freeze_thaw_trend"])),
    extreme_rain_change_pct: num(pick(r, ["extreme_rain_change_pct", "rain_change_pct"])),
    soil_moisture_index: num(pick(r, ["soil_moisture_index", "soil_moisture"])),
    baseline: toObj(pick(r, ["baseline_json", "baseline"])),
    projected: toObj(pick(r, ["projected_json", "projected"])),
    explanation: pick(r, ["explanation", "explanation_text"]),
    source: pick(r, ["source", "source_provenance", "provenance"]) || "W2_table",
    provenance: "live"
  };
}
function adaptAlert(r) {
  return { segment_id: r.segment_id, hazard: pick(r, ["hazard", "forecast_hazard", "hazard_type"]), severity: pick(r, ["severity", "alert_severity"]), event_date: pick(r, ["event_date", "date", "forecast_date"]), explanation: pick(r, ["explanation", "message"]), source: pick(r, ["source"]) || "W3_table", provenance: "live" };
}
function adaptAudit(r) {
  return { segment_id: r.segment_id, work_order_id: pick(r, ["work_order_id", "wo_id", "order_id"]), proposed_action: pick(r, ["proposed_action", "action"]), approval_status: String(pick(r, ["approval_status", "status"]) || "pending").toLowerCase(), override_tier: pick(r, ["override_tier"]), override_reason: pick(r, ["override_reason"]), created_at: pick(r, ["created_at", "createdAt"]), updated_at: pick(r, ["updated_at", "updatedAt"]), source: pick(r, ["source"]) || "W4_table", provenance: "live" };
}

// ---------- MOCK FIXTURES (DEMO ONLY - never live measurements) ----------
const MOCK_DRIVERS = ["Extreme-rainfall increase", "Freeze-thaw cycling", "Soil-moisture / slope instability", "Vegetation (NDVI) decline", "Slope + rainfall interaction"];
function mockPredictions(segs) {
  return segs.map(function (s, i) {
    const base = 28 + 58 * Math.abs(Math.sin(i * 1.7 + 0.5));
    const r10 = Math.round(base), r5 = Math.round(base * 0.78);
    const agree = Math.round((0.4 + 0.55 * Math.abs(Math.cos(i * 2.3))) * 100) / 100;
    const slope = i === 4 ? 12.4 : Math.round((0.8 + 8.5 * Math.pow(Math.abs(Math.sin(i * 0.9 + 1)), 2)) * 10) / 10;
    const rain = Math.round((4 + 16 * Math.abs(Math.sin(i * 1.1))) * 10) / 10;
    const ft = Math.round((-6 + 12 * Math.abs(Math.cos(i * 0.7))) * 10) / 10;
    const sm = Math.round((0.2 + 0.3 * Math.abs(Math.sin(i * 0.6))) * 100) / 100;
    const ndvi = Math.round((-0.08 * Math.abs(Math.sin(i * 1.3))) * 1000) / 1000;
    return {
      segment_id: s.segment_id, risk5_score: r5, risk5_tier: riskTier(r5, agree), risk10_score: r10, risk10_tier: riskTier(r10, agree),
      drivers: [MOCK_DRIVERS[i % 5], MOCK_DRIVERS[(i + 2) % 5]], model_agreement: agree, ndvi_trend: ndvi, slope_pct: slope,
      freeze_thaw_trend: ft, extreme_rain_change_pct: rain, soil_moisture_index: sm,
      baseline: { extreme_rain_days: 8, freeze_thaw_cycles: 60, soil_moisture: round(sm - 0.05, 2), ndvi: 0.62 },
      projected: { extreme_rain_days: round(8 * (1 + rain / 100), 1), freeze_thaw_cycles: round(60 + ft * 3, 0), soil_moisture: sm, ndvi: round(0.62 + ndvi, 3) },
      explanation: "DEMO FIXTURE - not a W2 model output. Replace by connecting the W2 predictions table.",
      source: "DEMO_FIXTURE_W2", provenance: "demo_fixture"
    };
  });
}
function mockAlerts(segs) {
  const hz = [["Heavy-rainfall washout", "moderate"], ["Rapid snowmelt / erosion", "low"], ["Flash-flood potential", "high"]];
  const out = [];
  segs.forEach(function (s, i) {
    if (i % 4 === 1) {
      const h = hz[(i >> 2) % 3];
      out.push({ segment_id: s.segment_id, hazard: h[0], severity: h[1], event_date: new Date(Date.now() + (2 + i) * 86400000).toISOString().slice(0, 10), explanation: "DEMO FIXTURE - not a W3 forecast.", source: "DEMO_FIXTURE_W3", provenance: "demo_fixture" });
    }
  });
  return out;
}
function mockAudit(segs, preds) {
  const out = [];
  const pb = {}; preds.forEach(function (p) { pb[p.segment_id] = p; });
  segs.forEach(function (s, i) {
    const p = pb[s.segment_id];
    if (p && (p.risk10_tier === "red" || p.risk10_tier === "red-uncertain" || (p.risk10_tier === "amber" && i % 3 === 0))) {
      const st = out.length % 3 === 0 ? "approved" : "pending";
      const t = new Date(Date.now() - (out.length + 1) * 3600000 * 7).toISOString();
      out.push({ segment_id: s.segment_id, work_order_id: "WO-DEMO-" + (100 + out.length), proposed_action: out.length % 2 ? "Slope reinforcement + drainage inspection" : "Ground-based integrity inspection", approval_status: st, override_tier: null, override_reason: null, created_at: t, updated_at: t, source: "DEMO_FIXTURE_W4", provenance: "demo_fixture" });
    }
  });
  return out;
}
function resolveUpstream(segs, rowsP, rowsA, rowsU) {
  const modes = {};
  let predictions = rowsP.map(adaptPrediction), alerts = rowsA.map(adaptAlert), audit = rowsU.map(adaptAudit);
  if (predictions.length) modes.predictions = "live"; else if (integrations.demoMode) { predictions = mockPredictions(segs); modes.predictions = "demo_fixture"; } else modes.predictions = "missing";
  if (alerts.length) modes.alerts = "live"; else if (integrations.demoMode) { alerts = mockAlerts(segs); modes.alerts = "demo_fixture"; } else modes.alerts = "missing";
  if (audit.length) modes.audit = "live"; else if (integrations.demoMode) { audit = mockAudit(segs, predictions); modes.audit = "demo_fixture"; } else modes.audit = "missing";
  return { predictions: predictions, alerts: alerts, audit: audit, modes: modes };
}

// ---------- BUILD LAYER CALCULATION (single implementation used by W5 and W6 demo preview) ----------
function isDemoLabel(l) { return typeof l === "string" && (l.indexOf("demo") === 0 || l.indexOf("synthetic") === 0); }
function calcBuild(inp, cfg) {
  const seg = inp.seg, lenM = num(seg.length_m);
  const geomAcres = lenM === null ? null : Math.min(cfg.buildStripM, 2 * cfg.studyStripWidthM) * lenM / 4046.8564224;
  const irr = num(inp.irradiance), slope = num(inp.slope), tier10 = inp.risk10_tier || "unverified", sub = num(inp.substation_km);
  const missing = [];
  if (irr === null) missing.push("irradiance");
  if (slope === null) missing.push("slope");
  if (tier10 === "unverified") missing.push("risk10");
  if (geomAcres === null) missing.push("length_m");
  const labels = { irradiance: inp.irrLabel || "missing", slope: inp.slopeLabel || "missing", risk10: inp.riskLabel || "missing", substation: inp.subLabel || "unavailable", geometry: inp.geomLabel || "unknown", usable_area_method: "approximation: length_m x total panel width (60 m default), capped by both study strips; outside the exclusion band", power_price: "sample assumption" };
  const row = {
    segment_id: seg.segment_id, corridor_id: seg.corridor_id || integrations.corridorId, build_score: null, build_tier: "unverified",
    usable_acres: round(geomAcres, 3), irradiance: round(irr, 3), slope_pct: slope, substation_km: round(sub, 2),
    mw: null, mwh_per_year: null, annual_lease_revenue: null, partner_annual_revenue: null, operator_annual_revenue: null, avoided_tco2_per_year: null, gross_power_value: null,
    risk10_tier: tier10, data_status: "unverified", data_labels: JSON.stringify(labels), calculated_at: nowIso(), missing_inputs: missing
  };
  if (missing.length) return row;
  const usable = slope > cfg.maxBuildSlopePct ? 0 : geomAcres;
  const mw = usable / cfg.acresPerMW;
  const mwh = mw * irr * 365 * cfg.performanceRatio;
  const lease = usable * cfg.leaseRatePerAcreYr;
  const sunFactor = clamp01((irr - 2.5) / 2.5);
  const slopeFactor = 1 - clamp01(slope / cfg.maxBuildSlopePct);
  const gridFactor = sub === null ? 0.5 : clamp01(1 - sub / 20);
  let score = 100 * (0.45 * sunFactor + 0.30 * slopeFactor + 0.25 * gridFactor);
  if (tier10 === "red" || tier10 === "red-uncertain") score *= cfg.riskPenaltyMultiplier;
  row.usable_acres = round(usable, 3);
  row.build_score = round(score, 1);
  row.build_tier = usable <= 0 ? "excluded" : (score >= 60 ? "green" : (score >= 40 ? "amber" : "grey"));
  row.mw = round(mw, 4); row.mwh_per_year = round(mwh, 1);
  row.annual_lease_revenue = round(lease, 2); row.partner_annual_revenue = round(lease * cfg.partnerShare, 2); row.operator_annual_revenue = round(lease * (1 - cfg.partnerShare), 2);
  row.avoided_tco2_per_year = round(mwh * cfg.gridEmissionFactor, 1);
  row.gross_power_value = round(mwh * cfg.powerPricePerMWh, 2);
  const demo = isDemoLabel(labels.irradiance) || isDemoLabel(labels.slope) || isDemoLabel(labels.risk10) || isDemoLabel(labels.geometry) || isDemoLabel(labels.substation);
  row.data_status = demo ? "demo_fixture" : "provisional";
  return row;
}
function rowsFrom(nodeName) {
  try { return $(nodeName).all().map(function (i) { return i.json; }).filter(function (j) { return j && j.segment_id && !j.error; }); } catch (e) { return []; }
}
// ================== END SHARED PRELUDE ==================

// Normalize the trigger payload (schedule / manual / execute-workflow / webhook).
const j = $input.first().json || {};
const isWebhook = j.headers !== undefined && j.body !== undefined;
const body = isWebhook ? (j.body && typeof j.body === "object" ? j.body : {}) : j;
let trigger;
if (isWebhook) trigger = "webhook_recalculate";
else if (typeof j.source === "string") trigger = j.source.slice(0, 40);
else trigger = $execution.mode === "manual" ? "manual" : "schedule";
const skipReport = isWebhook ? true : (typeof body.skip_report === "boolean" ? body.skip_report : false);
return [{ json: {
  integrations: integrations,
  request: {
    trigger: trigger,
    skip_report: skipReport,
    assumptions_override: body.assumptions && typeof body.assumptions === "object" ? body.assumptions : null,
    requested_at: nowIso()
  }
} }];

// ==================================================================
// TERRACORRIDOR SHARED ADAPTER PRELUDE (identical copy in W5 and W6)
// All upstream mappings (W1-W4), fixtures and the build-score formula
// live here. Edit ONLY this block to integrate W2/W3/W4.
// ==================================================================
const integrations = {
  demoMode: false,                       // true => mock fixtures allowed (always labelled demo_fixture)
  corridorId: "ab-strathcona-demo",
  segmentsTable: "euUFpWZEDrrDJOkc",  // W1 corridor_segments
  predictionsTable: "7T6RlFe9HRFOfkCD",  // W2 corridor_predictions (one row per segment and horizon)
  baselinesTable: "LckNoZvtBFwDnwM3",  // W2 corridor_baselines (slope, NDVI, baseline days)
  alertsTable: "sPlAgvMC7Q6sFHho",  // W3 near-term state lives in corridor_watch
  auditTable: "fWeMlbL9wQ5I7m3N",  // W4 corridor_work_orders (approval status per segment)
  buildTable: "E1GpvXaFTP4qLjsW",  // W5 corridor_build
  reportsTable: "T0PP8Zebw0vWU5KW",  // W5 corridor_reports
  configTable: "qfz2KdlrPsXlGkYO"  // W5 corridor_build_config
};

const DEFAULT_CONFIG = {
  acresPerMW: 6, performanceRatio: 0.8, leaseRatePerAcreYr: 400, partnerShare: 0.5,
  gridEmissionFactor: 0.5, maxBuildSlopePct: 10, riskPenaltyMultiplier: 0.5,
  powerPricePerMWh: 60,      // sample assumption (extension) - gross electricity value only, NOT lease revenue
  exclusionBandM: 30,        // metres each side of the centreline (approximation, see methodology)
  buildStripM: 60,          // total panel width across both sides, outside the exclusion band
  studyStripWidthM: 200      // strip width in metres each side, measured from the edge of the exclusion band (matches W1 geometry)
};
const RANGES = {
  acresPerMW: [1, 50], performanceRatio: [0.3, 1], leaseRatePerAcreYr: [0, 100000], partnerShare: [0, 1],
  gridEmissionFactor: [0, 2], maxBuildSlopePct: [1, 45], riskPenaltyMultiplier: [0, 1],
  powerPricePerMWh: [0, 2000], exclusionBandM: [0, 100], buildStripM: [10, 400], studyStripWidthM: [50, 500]
};

function num(v) { if (v === null || v === undefined || v === "") return null; const n = Number(v); return isFinite(n) ? n : null; }
function round(v, d) { if (v === null || v === undefined || !isFinite(v)) return null; const f = Math.pow(10, d); return Math.round(v * f) / f; }
function clamp01(x) { return Math.max(0, Math.min(1, x)); }
function nowIso() { return new Date().toISOString(); }
function pick(r, keys) { for (let i = 0; i < keys.length; i++) { const v = r[keys[i]]; if (v !== undefined && v !== null && v !== "") return v; } return null; }
